function initTheme(){const a=document.getElementById("theme-toggle");a&&a.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark"),a.textContent=e?"☀️":"🌙"})}function initScrollTop(){const a=document.getElementById("btn-scroll-top");a&&(window.addEventListener("scroll",()=>{a.classList.toggle("visible",window.scrollY>400)}),a.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}))}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initScrollTop(),renderDynasties(),initFilters()});const dynastiesData=[{id:"koppam",name:"Battle of Koppam",region:"deccan",period:"medieval",religion:"hinduism",capital:"Koppam (Battlefield)",dates:"1050s CE",description:"The fierce struggle for Deccan supremacy between the Cholas and the Western Chalukyas.",icon:"⚔️",link:"../battle-koppam/index.html"},{id:"kakatiya",name:"Kakatiya Dynasty",region:"south",period:"medieval",religion:"hinduism",capital:"Orugallu (Warangal)",dates:"1163 - 1323 CE",description:"Renowned for architectural marvels like the Ramappa Temple and advanced irrigation systems in the Deccan.",icon:"🏛️",link:"../kakatiya-dynasty/index.html"},{id:"eastern-ganga",name:"Eastern Ganga Dynasty",region:"east",period:"medieval",religion:"hinduism",capital:"Kalingapatnam / Cuttack",dates:"1078 - 1434 CE",description:"Master builders of Odisha, responsible for the Konark Sun Temple and the expansion of the Jagannath Temple.",icon:"☀️",link:"../eastern-ganga-dynasty/index.html"},{id:"pala",name:"Pala Dynasty",region:"east",period:"ancient",religion:"buddhism",capital:"Pataliputra / Gauda",dates:"750 - 1174 CE",description:"Great patrons of Mahayana Buddhism, founders of universities like Vikramashila and Somapura Mahavihara.",icon:"☸️",link:"../pala-dynasty/index.html"},{id:"chola",name:"Chola Dynasty",region:"south",period:"medieval",religion:"hinduism",capital:"Thanjavur",dates:"848 - 1279 CE",description:"A maritime empire that dominated the Indian Ocean, built the Brihadeeswarar Temple, and spread Indian culture to Southeast Asia.",icon:"⚓",link:"#"},{id:"maurya",name:"Maurya Empire",region:"pan-india",period:"ancient",religion:"buddhism",capital:"Pataliputra",dates:"322 - 185 BCE",description:"The first pan-Indian empire, unified the subcontinent under Chandragupta and Ashoka, spreading Buddhism across Asia.",icon:"🦁",link:"#"},{id:"gupta",name:"Gupta Empire",region:"north",period:"ancient",religion:"hinduism",capital:"Pataliputra",dates:"320 - 550 CE",description:"The Golden Age of India, marked by significant advancements in science, mathematics, astronomy, and classical art.",icon:"✨",link:"#"},{id:"mughal",name:"Mughal Empire",region:"pan-india",period:"early-modern",religion:"islam",capital:"Agra / Delhi",dates:"1526 - 1857 CE",description:"Known for monumental architecture like the Taj Mahal, centralized administration, and cultural synthesis.",icon:"🕌",link:"#"},{id:"rashtrakuta",name:"Rashtrakuta Dynasty",region:"deccan",period:"medieval",religion:"hinduism",capital:"Manyakheta",dates:"c. 753 - 982 CE",description:"Military titans of the Deccan and patrons of the monolithic Kailash Temple at Ellora.",icon:"⚔️",link:"../rashtrakuta-dynasty-explorer/index.html"},{id:"pallava",name:"Pallava Dynasty",region:"south",period:"ancient",religion:"hinduism",capital:"Kanchipuram",dates:"c. 275 - 897 CE",description:"Pioneers of Dravidian rock-cut and structural temple architecture at Kanchipuram and Mahabalipuram.",icon:"🛕",link:"../pallava-dynasty-explorer/index.html"},{id:"maratha",name:"Maratha Empire",region:"west",period:"early-modern",religion:"hinduism",capital:"Raigad / Pune",dates:"1674 - 1818 CE",description:"Founded by Shivaji Maharaj, the Marathas challenged Mughal dominance and established a vast confederacy across India.",icon:"⚔️",link:"#"},{id:"chalukya",name:"Western Chalukya",region:"deccan",period:"medieval",religion:"hinduism",capital:"Badami / Kalyani",dates:"543 - 1189 CE",description:"Patrons of Kannada and Sanskrit literature, known for the distinctive Vesara style of temple architecture at Pattadakal and Badami.",icon:"🏰",link:"../chalukya-dynasty-explorer/index.html"},{id:"pandya",name:"Pandya Dynasty",region:"south",period:"ancient",religion:"hinduism",capital:"Madurai",dates:"c. 300 BCE - 1345 CE",description:"A Tamil dynasty celebrated for Gulf of Mannar pearls, Madurai culture and temple patronage.",icon:"🦪",link:"../pandya-dynasty-explorer/index.html"},{id:"chera",name:"Chera Dynasty",region:"south",period:"ancient",religion:"hinduism",capital:"Vanchi / Mahodayapuram",dates:"c. 300 BCE - 1120 CE",description:"A western Tamil and Kerala dynasty known for pepper trade, Sangam culture and Malabar ports.",icon:"⚓",link:"../chera-dynasty-explorer/index.html"},{id:"jodhpur-marwar",name:"Kingdom of Jodhpur (Marwar)",region:"west",period:"medieval",religion:"hinduism",capital:"Jodhpur",dates:"c. 1226 - 1949 CE",description:"The Rathore Rajputs of Marwar built the mighty Mehrangarh Fort, fostered the Marwari trade network, and kept their desert kingdom unconquered for seven centuries.",icon:"🏰",link:"../Jodhpur-Marwar/JodhpurMarwar.html"},{id:"satavahana",name:"Satavahana Dynasty",region:"deccan",period:"ancient",religion:"hinduism",capital:"Pratishthana / Amaravati",dates:"c. 100 BCE - 220 CE",description:"Lords of Dakshinapatha known for maritime trade with Rome, ship coins, and Amaravati stupa art.",icon:"⛵",link:"../satavahana-dynasty-explorer/index.html"},{id:"vijayanagara",name:"Vijayanagara Empire",region:"south",period:"medieval",religion:"hinduism",capital:"Hampi",dates:"1336 - 1646 CE",description:"A wealthy and powerful empire that served as a bulwark against southern invasions, famous for the ruins of Hampi.",icon:"🐘",link:"#"}];function renderDynasties(){const a=document.getElementById("dynasties-container"),e=document.getElementById("results-count"),i=document.getElementById("no-results"),n=document.getElementById("dynasty-search").value.toLowerCase(),t=document.getElementById("filter-region").value,r=document.getElementById("filter-period").value,d=document.getElementById("filter-religion").value,o=dynastiesData.filter(a=>{const e=a.name.toLowerCase().includes(n)||a.capital.toLowerCase().includes(n)||a.description.toLowerCase().includes(n),i="all"===t||a.region===t,o="all"===r||a.period===r,s="all"===d||a.religion===d;return e&&i&&o&&s});0===o.length?(a.innerHTML="",i.style.display="block",e.textContent="No dynasties found"):(i.style.display="none",e.textContent=`Showing ${o.length} dynasties`,a.innerHTML=o.map(a=>`\n            <div class="dynasty-card" onclick="window.location.href='${a.link}'">\n                <div class="card-header">\n                    <span class="card-region-badge">${a.region.replace("-"," ")}</span>\n                    <div class="card-icon">${a.icon}</div>\n                </div>\n                <div class="card-body">\n                    <h3>${a.name}</h3>\n                    <div class="card-period">${a.dates}</div>\n                    <p class="card-description">${a.description}</p>\n                    <div class="card-meta">\n                        <span>🏛️ ${a.capital}</span>\n                        <span>🛡️ ${a.religion}</span>\n                    </div>\n                </div>\n            </div>\n        `).join(""))}function initFilters(){["dynasty-search","filter-region","filter-period","filter-religion"].forEach(a=>{const e=document.getElementById(a);e&&(e.addEventListener("input",renderDynasties),e.addEventListener("change",renderDynasties))}),renderDynasties()}